namespace ShipmentTracker.Client.Models;

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string? RecipientEmail { get; set; }
}

public enum ShipmentStatus
{
    Pending,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}

using System.ComponentModel.DataAnnotations;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }
    [Required, MaxLength(20)]
    public string TrackingNumber { get; set; } = string.Empty;
    [Required, MaxLength(200)]
    public string Origin { get; set; } = string.Empty;
    [Required, MaxLength(200)]
    public string Destination { get; set; } = string.Empty;
    public int Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string? RecipientEmail { get; set; }
    public string? AssignedDispatcherId { get; set; }
}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        // Get all shipments (dispatchers)
        group.MapGet("/", async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.ShippedDate)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = (ShipmentStatus)s.Status,
                    ShippedDate = s.ShippedDate,
                    EstimatedDelivery = s.EstimatedDelivery,
                    RecipientEmail = s.RecipientEmail
                })
                .ToListAsync();
            return Results.Ok(shipments);
        });

        // Track a shipment by tracking number (customers)
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            if (shipment is null)
                return Results.NotFound();
            return Results.Ok(new ShipmentDto
            {
                Id = shipment.Id,
                TrackingNumber = shipment.TrackingNumber,
                Origin = shipment.Origin,
                Destination = shipment.Destination,
                Status = (ShipmentStatus)shipment.Status,
                ShippedDate = shipment.ShippedDate,
                EstimatedDelivery = shipment.EstimatedDelivery
            });
        });

        // Create a shipment (dispatchers)
        group.MapPost("/", async (ShipmentDto dto, ApplicationDbContext db) =>
        {
            var shipment = new Shipment
            {
                TrackingNumber = dto.TrackingNumber,
                Origin = dto.Origin,
                Destination = dto.Destination,
                Status = (int)dto.Status,
                ShippedDate = dto.ShippedDate,
                EstimatedDelivery = dto.EstimatedDelivery,
                RecipientEmail = dto.RecipientEmail
            };
            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            dto.Id = shipment.Id;
            return Results.Created($"/api/shipments/{shipment.Id}", dto);
        });

        // Update shipment status (dispatchers)
        group.MapPut("/{id:int}/status", async (int id, ShipmentStatusUpdate update, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null)
                return Results.NotFound();
            shipment.Status = (int)update.Status;
            if (update.EstimatedDelivery.HasValue)
                shipment.EstimatedDelivery = update.EstimatedDelivery.Value;
            await db.SaveChangesAsync();
            return Results.NoContent();
        });
    }
}

public record ShipmentStatusUpdate(ShipmentStatus Status, DateTime? EstimatedDelivery);

using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public static class SeedData
{
    public static async Task InitializeAsync(IServiceProvider serviceProvider)
    {
        using var scope = serviceProvider.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
        await db.Database.MigrateAsync();

        if (await db.Shipments.AnyAsync())
            return;

        db.Shipments.AddRange(
            new Shipment { TrackingNumber = "TRK-001", Origin = "New York, US", Destination = "London, UK", Status = 1, ShippedDate = DateTime.Today.AddDays(-3), EstimatedDelivery = DateTime.Today.AddDays(4), RecipientEmail = "customer1@example.com" },
            new Shipment { TrackingNumber = "TRK-002", Origin = "Tokyo, JP", Destination = "Sydney, AU", Status = 2, ShippedDate = DateTime.Today.AddDays(-1), EstimatedDelivery = DateTime.Today.AddDays(2), RecipientEmail = "customer2@example.com" },
            new Shipment { TrackingNumber = "TRK-003", Origin = "Berlin, DE", Destination = "Paris, FR", Status = 3, ShippedDate = DateTime.Today.AddDays(-7), EstimatedDelivery = DateTime.Today.AddDays(-1), RecipientEmail = "customer3@example.com" },
            new Shipment { TrackingNumber = "TRK-004", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = 0, ShippedDate = DateTime.Today, EstimatedDelivery = DateTime.Today.AddDays(10) },
            new Shipment { TrackingNumber = "TRK-005", Origin = "Mumbai, IN", Destination = "Dubai, AE", Status = 4, ShippedDate = DateTime.Today.AddDays(-5), EstimatedDelivery = DateTime.Today.AddDays(3), RecipientEmail = "customer5@example.com" }
        );
        await db.SaveChangesAsync();
    }
}

@page "/shipments"
@using ShipmentTracker.Client.Models
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject HttpClient Http

<PageTitle>Shipments - Dispatch Dashboard</PageTitle>

<h2>Dispatch Dashboard</h2>

<div class="mb-3">
    <button class="btn btn-primary" @onclick="ShowCreateForm">+ New Shipment</button>
</div>

@if (showCreate)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5>Create Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input class="form-control" placeholder="Tracking #" @bind="newShipment.TrackingNumber" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" type="email" placeholder="Recipient Email" @bind="newShipment.RecipientEmail" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Shipped</label>
                    <input class="form-control" type="date" @bind="newShipment.ShippedDate" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Est. Delivery</label>
                    <input class="form-control" type="date" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-md-3 d-flex align-items-end">
                    <button class="btn btn-success me-2" @onclick="CreateShipment">Save</button>
                    <button class="btn btn-secondary" @onclick="() => showCreate = false">Cancel</button>
                </div>
            </div>
            @if (!string.IsNullOrEmpty(createError))
            {
                <div class="alert alert-danger mt-2">@createError</div>
            }
        </div>
    </div>
}

@if (shipments is null)
{
    <p>Loading shipments...</p>
}
else if (!shipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in shipments)
            {
                <tr>
                    <td>@s.TrackingNumber</td>
                    <td>@s.Origin</td>
                    <td>@s.Destination</td>
                    <td><span class="badge bg-@GetStatusColor(s.Status)">@s.Status</span></td>
                    <td>@s.ShippedDate.ToShortDateString()</td>
                    <td>@s.EstimatedDelivery.ToShortDateString()</td>
                    <td>
                        <select class="form-select form-select-sm" style="width:auto;display:inline-block"
                                value="@((int)s.Status)"
                                @onchange="(e) => UpdateStatus(s, e)">
                            @foreach (ShipmentStatus status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@((int)status)">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentDto>? shipments;
    private bool showCreate;
    private ShipmentDto newShipment = new() { ShippedDate = DateTime.Today, EstimatedDelivery = DateTime.Today.AddDays(5) };
    private string? createError;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
    }

    private void ShowCreateForm()
    {
        showCreate = true;
        createError = null;
        newShipment = new() { ShippedDate = DateTime.Today, EstimatedDelivery = DateTime.Today.AddDays(5) };
    }

    private async Task CreateShipment()
    {
        createError = null;
        var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
        if (response.IsSuccessStatusCode)
        {
            showCreate = false;
            await LoadShipments();
        }
        else
        {
            createError = "Failed to create shipment. Ensure tracking number is unique.";
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out var statusVal))
        {
            var update = new { Status = (ShipmentStatus)statusVal, EstimatedDelivery = (DateTime?)null };
            await Http.PutAsJsonAsync($"/api/shipments/{shipment.Id}/status", update);
            shipment.Status = (ShipmentStatus)statusVal;
        }
    }

    private static string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.InTransit => "primary",
        ShipmentStatus.OutForDelivery => "info",
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.Delayed => "warning",
        _ => "secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject HttpClient Http

<PageTitle>Track Shipment</PageTitle>

<h2>Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input class="form-control" placeholder="Enter tracking number" @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading) { <span class="spinner-border spinner-border-sm"></span> }
                Track
            </button>
        </div>
    </div>
</div>

@if (notFound)
{
    <div class="alert alert-warning">No shipment found with that tracking number.</div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <strong>Shipment @shipment.TrackingNumber</strong>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                        <dt>Shipped Date</dt>
                        <dd>@shipment.ShippedDate.ToShortDateString()</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge bg-@GetStatusColor(shipment.Status) fs-6">@shipment.Status</span></dd>
                        <dt>Estimated Delivery</dt>
                        <dd class="fs-5 fw-bold">@shipment.EstimatedDelivery.ToShortDateString()</dd>
                    </dl>
                </div>
            </div>

            <div class="mt-3">
                <h6>Delivery Progress</h6>
                <div class="progress" style="height: 25px;">
                    <div class="progress-bar bg-@GetStatusColor(shipment.Status)" role="progressbar"
                         style="width: @(GetProgress(shipment.Status))%">
                        @shipment.Status
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private ShipmentDto? shipment;
    private bool notFound;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isLoading = true;
        notFound = false;
        shipment = null;

        try
        {
            var response = await Http.GetAsync($"/api/shipments/track/{Uri.EscapeDataString(trackingNumber.Trim())}");
            if (response.IsSuccessStatusCode)
                shipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
            else
                notFound = true;
        }
        catch
        {
            notFound = true;
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.InTransit => "primary",
        ShipmentStatus.OutForDelivery => "info",
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.Delayed => "warning",
        _ => "secondary"
    };

    private static int GetProgress(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.InTransit => 40,
        ShipmentStatus.OutForDelivery => 75,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 50,
        _ => 0
    };
}

